-- Idempotent parity for local CLI restores; Drizzle owns hosted migrations.
CREATE TABLE IF NOT EXISTS public.operational_settings (id boolean PRIMARY KEY DEFAULT true, email_enabled boolean NOT NULL DEFAULT false, alert_email text NOT NULL DEFAULT '', slack_enabled boolean NOT NULL DEFAULT false, slack_channel text NOT NULL DEFAULT '', alert_failures boolean NOT NULL DEFAULT true, alert_regressions boolean NOT NULL DEFAULT true, alert_high boolean NOT NULL DEFAULT true, block_catalog boolean NOT NULL DEFAULT true, retention_days integer NOT NULL DEFAULT 0, CONSTRAINT singleton_id CHECK(id), CONSTRAINT retention_range CHECK(retention_days BETWEEN 0 AND 3650));
GRANT SELECT,INSERT,UPDATE ON public.operational_settings TO authenticated;
GRANT ALL ON public.operational_settings TO service_role;
ALTER TABLE public.operational_settings ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.catalog_security_approvals (scan_id uuid PRIMARY KEY REFERENCES public.security_scan_runs(id), approved_by uuid NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.catalog_security_approvals TO authenticated;
GRANT ALL ON public.catalog_security_approvals TO service_role;
ALTER TABLE public.catalog_security_approvals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.security_scan_runs ADD COLUMN IF NOT EXISTS high_regression boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.catalog_security_status() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scan public.security_scan_runs; enabled boolean; approved boolean; BEGIN IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; SELECT coalesce(block_catalog,true) INTO enabled FROM public.operational_settings LIMIT 1; enabled:=coalesce(enabled,true); SELECT * INTO scan FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1; SELECT EXISTS(SELECT 1 FROM public.catalog_security_approvals WHERE scan_id=scan.id) INTO approved; RETURN jsonb_build_object('blocked',enabled AND (scan.high_regression OR (scan.regression AND scan.high_count+scan.critical_count>0)) AND NOT approved,'scan_id',scan.id,'approved',approved); END; $$;
REVOKE ALL ON FUNCTION public.catalog_security_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.catalog_security_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.approve_catalog_security(_scan_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF length(btrim(_reason))<10 THEN RAISE EXCEPTION 'Provide a detailed approval reason'; END IF; IF _scan_id IS DISTINCT FROM (SELECT id FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1) THEN RAISE EXCEPTION 'Scan changed, refresh first'; END IF; INSERT INTO public.catalog_security_approvals(scan_id,approved_by,reason) VALUES(_scan_id,auth.uid(),btrim(_reason)) ON CONFLICT(scan_id) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.approve_catalog_security(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.approve_catalog_security(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_catalog_security() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scan public.security_scan_runs; enabled boolean; BEGIN SELECT coalesce(block_catalog,true) INTO enabled FROM public.operational_settings LIMIT 1; IF coalesce(enabled,true) THEN SELECT * INTO scan FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1; IF (scan.high_regression OR (scan.regression AND scan.high_count+scan.critical_count>0)) AND NOT EXISTS(SELECT 1 FROM public.catalog_security_approvals WHERE scan_id=scan.id) THEN RAISE EXCEPTION 'Catalog blocked: high security regression. Request approval in Admin Security.' USING ERRCODE='42501'; END IF; END IF; RETURN NULL; END; $$;
CREATE OR REPLACE FUNCTION public.cleanup_web_vitals_history() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days integer; removed integer; BEGIN SELECT retention_days INTO days FROM public.operational_settings LIMIT 1; IF coalesce(days,0)=0 THEN RETURN 0; END IF; DELETE FROM public.web_vitals_reports WHERE created_at < now()-make_interval(days=>days); GET DIAGNOSTICS removed=ROW_COUNT; RETURN removed; END; $$;
REVOKE ALL ON FUNCTION public.cleanup_web_vitals_history() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_web_vitals_history() TO service_role;
CREATE OR REPLACE FUNCTION public.retry_image_processing_job(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; UPDATE public.image_processing_jobs SET status='pending',attempts=0,error=NULL,processed_at=NULL WHERE id=_id AND status IN ('error','retry'); IF NOT FOUND THEN RAISE EXCEPTION 'Job is not eligible for retry'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.retry_image_processing_job(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.retry_image_processing_job(uuid) TO authenticated;
CREATE TABLE IF NOT EXISTS public.operational_worker_credentials (id boolean PRIMARY KEY DEFAULT true CHECK(id), token text NOT NULL DEFAULT (gen_random_uuid()::text || gen_random_uuid()::text));
GRANT ALL ON public.operational_worker_credentials TO service_role;
ALTER TABLE public.operational_worker_credentials ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.operational_worker_headers() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE secret text; BEGIN INSERT INTO public.operational_worker_credentials(id) VALUES(true) ON CONFLICT DO NOTHING; SELECT token INTO secret FROM public.operational_worker_credentials WHERE id=true; RETURN jsonb_build_object('Content-Type','application/json','x-operational-secret',secret); END; $$;
REVOKE ALL ON FUNCTION public.operational_worker_headers() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.operational_worker_headers() TO service_role;
ALTER TABLE public.image_processing_jobs ADD COLUMN IF NOT EXISTS claim_token uuid, ADD COLUMN IF NOT EXISTS lease_expires_at timestamptz;
REVOKE UPDATE ON public.image_processing_jobs FROM authenticated;
CREATE OR REPLACE FUNCTION public.claim_image_processing_jobs(_limit integer DEFAULT 5) RETURNS SETOF public.image_processing_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.image_processing_jobs SET status='error',error='Processing lease expired; retry required',lease_expires_at=NULL,claim_token=NULL WHERE status='processing' AND coalesce(lease_expires_at,updated_at+interval '10 minutes') < now() AND attempts>=3; RETURN QUERY WITH candidates AS (SELECT id FROM public.image_processing_jobs WHERE attempts<3 AND (status IN ('pending','retry') OR (status='processing' AND coalesce(lease_expires_at,updated_at+interval '10 minutes')<now())) ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT greatest(1,least(_limit,5))) UPDATE public.image_processing_jobs j SET status='processing',attempts=j.attempts+1,claim_token=gen_random_uuid(),lease_expires_at=now()+interval '10 minutes' FROM candidates c WHERE j.id=c.id RETURNING j.*; END; $$;
REVOKE ALL ON FUNCTION public.claim_image_processing_jobs(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_image_processing_jobs(integer) TO service_role;
CREATE OR REPLACE FUNCTION public.unresolved_catalog_security_scan() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH latest AS (SELECT findings FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1) SELECT r.id FROM public.security_scan_runs r WHERE r.status='ok' AND r.high_regression AND NOT EXISTS(SELECT 1 FROM public.catalog_security_approvals a WHERE a.scan_id=r.id) AND EXISTS (SELECT 1 FROM jsonb_array_elements(r.findings) f CROSS JOIN latest l CROSS JOIN LATERAL jsonb_array_elements(l.findings) c WHERE f->>'severity' IN ('high','critical') AND c->>'severity' IN ('high','critical') AND f->>'id'=c->>'id' AND f->>'package'=c->>'package') ORDER BY r.created_at DESC,r.id DESC LIMIT 1; $$;
REVOKE ALL ON FUNCTION public.unresolved_catalog_security_scan() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.catalog_security_status() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE blocked_scan uuid; enabled boolean; BEGIN IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; SELECT coalesce(block_catalog,true) INTO enabled FROM public.operational_settings WHERE id=true; blocked_scan:=public.unresolved_catalog_security_scan(); RETURN jsonb_build_object('blocked',coalesce(enabled,true) AND blocked_scan IS NOT NULL,'scan_id',blocked_scan,'approved',false); END; $$;
CREATE OR REPLACE FUNCTION public.enforce_catalog_security() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce((SELECT block_catalog FROM public.operational_settings WHERE id=true),true) AND public.unresolved_catalog_security_scan() IS NOT NULL THEN RAISE EXCEPTION 'Catalog blocked: unresolved high security regression. Request approval in Admin Security.' USING ERRCODE='42501'; END IF; RETURN NULL; END; $$;
CREATE OR REPLACE FUNCTION public.approve_catalog_security(_scan_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF _reason IS NULL OR length(btrim(_reason))<10 THEN RAISE EXCEPTION 'Provide a detailed approval reason'; END IF; IF _scan_id IS NULL OR _scan_id IS DISTINCT FROM public.unresolved_catalog_security_scan() THEN RAISE EXCEPTION 'Blocking scan changed, refresh first'; END IF; INSERT INTO public.catalog_security_approvals(scan_id,approved_by,reason) VALUES(_scan_id,auth.uid(),btrim(_reason)) ON CONFLICT(scan_id) DO NOTHING; END; $$;
DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='operational_settings' AND policyname='admin_operational_settings') THEN CREATE POLICY admin_operational_settings ON public.operational_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin')); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='catalog_security_approvals' AND policyname='admin_read_approvals') THEN CREATE POLICY admin_read_approvals ON public.catalog_security_approvals FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin')); END IF;
END $$;
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['products','product_tags','product_occasions','product_segments'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('public.'||tbl)::regclass AND tgname='catalog_security_gate') THEN EXECUTE format('CREATE TRIGGER catalog_security_gate BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_catalog_security()',tbl); END IF; END LOOP; END $$;
